import{onetQuestions}from'./onet-assessment.js';import{discoveryTopics056}from'./open-explorer-056.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),ul=xs=>'<ul>'+xs.map(x=>'<li>'+h(x)+'</li>').join('')+'</ul>';
export function structuredModelHTML(c){const b=c.biography;return '<h1>'+h(b.name)+'</h1><p>'+h(c.id)+' · '+h(c.phase==='holdout056'?'New holdout · fixed-rule evaluation only':'Additional development')+' · structured synthetic case</p><p>Generated from frozen activity, method and responsibility preferences. This case is not an observed student or an independently authored life story. Background and health labels are excluded from career-answer generation.</p><nav><a href="./model-match-chart.html?query='+encodeURIComponent(c.id)+'">Current matches & evidence →</a> · <a href="../student-view.html?case='+encodeURIComponent(c.id)+'&amp;replay=final#/journey/explore">Explore as this model →</a> · <a href="./cohort-matrix.html?query='+encodeURIComponent(c.id)+'&amp;view=profiles">Cohort characteristics →</a></nav><details id="history" open><summary>Full profile</summary><p>Age '+h(b.age)+' · '+h(b.pronouns)+'</p><dl>'+Object.entries(b.background).map(([k,v])=>'<dt>'+h(k)+'</dt><dd>'+h(v)+'</dd>').join('')+'</dl>'+b.timeline.map(t=>'<h3>Age '+h(t.ages)+'</h3><p>'+h(t.story)+'</p>').join('')+Object.entries(b.currentLife).map(([k,values])=>'<h3>'+h(k.replace(/[A-Z]/g,x=>' '+x.toLowerCase()))+'</h3>'+ul(values)).join('')+'</details><section id="profile"><h2>Saved simulation answers</h2><p><a href="./cohort-056-structured-inputs.json">Frozen topic, method and responsibility IDs · all added profiles</a> · <a href="./cohort-056-question-bindings.json">Question and option mappings</a></p><p>Neutral official responses can mean unknown preference in this simulator. They are not claims of disinterest. No career has been chosen. This replay answers all mapped subject-aligned career questions; it is not a prediction of typical survey completion.</p><details><summary>60 official interest responses</summary><ol>'+onetQuestions.map((q,i)=>'<li>'+h(q.text)+'<br><strong>'+c.response.official[i]+' / 5</strong> · '+h(c.response.responseRationales[i].reason)+'</li>').join('')+'</ol></details><details><summary>Neutral activity preferences</summary><ul>'+discoveryTopics056.map(t=>{const a=c.experimentState.explorer053.facetAnswers['topic056-'+t.id];return'<li>'+h(t.title)+' · '+h(a?.value>=4?'Would explore':a?.value<=2?'Does not currently enjoy':'Unfamiliar / unknown')+'<p>'+h(a?.evidence)+'</p></li>';}).join('')+'</ul></details><details><summary>All saved general and field answers</summary><pre>'+h(JSON.stringify({general:c.experimentState.explorer053.facetAnswers,field:c.experimentState.explorer053.fieldAnswers},null,2))+'</pre></details><details><summary>Profession clarification answers · '+c.response.professionAnswers.length+'</summary>'+c.response.professionAnswers.map(a=>'<article><h3>'+h(a.prompt)+'</h3><p>'+h(a.response)+' · '+h(a.confidence)+' confidence · procedural profile inference</p><p>'+h(a.evidence)+'</p><p>'+h(a.limitation)+'</p></article>').join('')+'</details><p>Optional fields chosen: '+h(c.cohort056.selectedFields.join(' · ')||'None')+'. Study openness: '+h(c.cohort056.studyOpenness)+'.</p><p>Screen counts: '+h(JSON.stringify(c.cohort056.screenCounts))+'. Extra topic selections are an optional single-page preference collection.</p></section>';}
